public int findMaxSubsequenceLength(int[] A, int N, int D) {
    if (N == 0) return 0;

    int maxLength = 1;
    int currentLength = 1;

    for (int i = 1; i < N; i++) {
        if (Math.abs(A[i] - A[i - 1]) <= D) {
            currentLength++;
        } else {
            currentLength = 1;
        }
        maxLength = Math.max(maxLength, currentLength);
    }

    return maxLength;
}
